mapper.select:
SELECT t.*, t.SOURCE_SYSTEM_ID source_id, s.NAME source_name, s.CODE source_code, s.ICON source_icon, m.ICON model_icon, m.TYPE model_type, m.DESCRIPTION model_description, v.STATUS model_version_status, COALESCE(rv.VERSION_NO, v.VERSION_NO) model_version_no, s.TRUST_SCORE source_trust_score, m.NAME model_name, m.CODE model_code, d.DATASOURCE_NAME datasource_name, c.SOURCE_OBJECT fetch_source_object, f.FILE_NAME fetch_file_name, a.URL fetch_api_url, a.HTTP_METHOD fetch_http_method, latest.START_TIME last_run_time, latest.STATUS last_run_status, latest.END_TIME last_run_end_time, COALESCE(u.NICK_NAME, u.USER_NAME) responsible_person_name, u.PHONENUMBER responsible_person_phone, cu.PHONENUMBER createPhoneNumber FROM INGEST_TASK t LEFT JOIN INGEST_SOURCE_SYSTEM s ON s.ID=t.SOURCE_SYSTEM_ID LEFT JOIN MODEL_BASE m ON m.ID=t.MODEL_ID LEFT JOIN MODEL_VERSION v ON v.ID=m.VERSION_ID AND v.DEL_FLAG='0' LEFT JOIN MODEL_BASE published_model ON published_model.ID=CASE WHEN m.PARENT_ID IS NULL OR m.PARENT_ID=0 THEN m.ID ELSE m.PARENT_ID END AND published_model.DEL_FLAG='0' LEFT JOIN MODEL_INSTANCE published_instance ON published_instance.ID=published_model.PUBLISHED_INSTANCE_ID AND published_instance.MODEL_ID=published_model.ID AND published_instance.STATUS='SUCCEEDED' LEFT JOIN MODEL_VERSION rv ON rv.ID=published_instance.MODEL_VERSION_ID AND rv.MODEL_ID=published_model.ID AND rv.DEL_FLAG='0' LEFT JOIN SYSTEM_USER u ON u.USER_ID=t.RESPONSIBLE_USER_ID AND u.DEL_FLAG='0' LEFT JOIN SYSTEM_USER cu ON cu.USER_ID=t.CREATOR_ID AND cu.DEL_FLAG='0' LEFT JOIN INGEST_TASK_DB_CONFIG c ON c.TASK_ID=t.ID AND c.DEL_FLAG='0' AND t.TYPE='DATABASE' LEFT JOIN INGEST_DATASOURCE d ON d.ID=c.DATASOURCE_ID LEFT JOIN INGEST_TASK_FILE_CONFIG f ON f.TASK_ID=t.ID AND f.DEL_FLAG='0' AND t.TYPE='FILE' LEFT JOIN INGEST_TASK_API_CONFIG a ON a.TASK_ID=t.ID AND a.DEL_FLAG='0' AND t.TYPE='API' LEFT JOIN ( SELECT TASK_ID, START_TIME, END_TIME, STATUS, ROW_NUMBER() OVER (PARTITION BY TASK_ID ORDER BY START_TIME DESC, ID DESC) rn FROM INGEST_TASK_INSTANCE WHERE DEL_FLAG='0' ) latest ON latest.TASK_ID=t.ID AND latest.rn=1 WHERE t.DEL_FLAG='0'
AND (t.NAME LIKE #{keywordPattern} OR t.CODE LIKE #{keywordPattern})
AND t.NAME LIKE #{namePattern}
AND t.CODE LIKE #{codePattern}
AND t.SOURCE_SYSTEM_ID=#{q.sourceId}
AND t.MODEL_ID=#{q.modelId}
AND t.TYPE=#{q.type}
AND t.STATUS=#{q.status}
ORDER BY t.ID
ASC DESC
ORDER BY t.CREATE_TIME
ASC, t.ID ASC DESC, t.ID DESC
ORDER BY t.UPDATE_TIME DESC
